module pisa_levitation (\n    input clk,\n    input rst_n,\n    input start,\n    input [3:0] A,\n    input [3:0] B,\n    input [3:0] left [0:7],\n    input [3:0] right [0:7],\n    input [0:7] t,\n    output reg [8:0] result,\n    output reg done\n);\n\nparameter N = 8;\n\n// State definitions\nlocalparam [2:0] IDLE = 3'b000;\nlocalparam [2:0] CHECK = 3'b001;\nlocalparam [2:0] ENQUEUE_LEFT = 3'b010;\nlocalparam [2:0] ENQUEUE_RIGHT = 3'b011;\nlocalparam [2:0] SWAP = 3'b100;\nlocalparam [2:0] DONE = 3'b101;\nlocalparam [2:0] INDIST = 3'b110;\n\nreg [2:0] state;\nreg [255:0] visited;\nreg [7:0] queue_curr [0:255];\nreg [7:0] queue_next [0:255];\nreg [7:0] curr_read_ptr, curr_write_ptr;\nreg [7:0] next_write_ptr;\nreg [7:0] curr_count, next_count;\nreg [7:0] step;\nreg [3:0] a, b, next_a, next_b;\nreg [7:0] state_index;\ninteger i;\n\nalways @(posedge clk or negedge rst_n) begin\n    if (!rst_n) begin\n        state <= IDLE;\n        visited <= 256'd0;\n        curr_read_ptr <= 8'd0;\n        curr_write_ptr <= 8'd0;\n        next_write_ptr <= 8'd0;\n        curr_count <= 8'd0;\n        next_count <= 8'd0;\n        step <= 8'd0;\n        done <= 1'b0;\n        result <= 9'd0;\n        for (i = 0; i < 256; i = i + 1) begin\n            queue_curr[i] <= 8'd0;\n            queue_next[i] <= 8'd0;\n        end\n    end else begin\n        case (state)\n            IDLE: begin\n                if (start) begin\n                    visited <= 256'd0;\n                    visited[{A,B}] <= 1'b1;\n                    queue_curr[0] <= {A,B};\n                    curr_write_ptr <= 8'd1;\n                    curr_count <= 8'd1;\n                    step <= 8'd0;\n                    done <= 1'b0;\n                    state <= CHECK;\n                end\n            end\n\n            CHECK: begin\n                if (curr_count == 8'd0) begin\n                    if (next_count == 8'd0) begin\n                        state <= INDIST;\n                    end else begin\n                        state <= SWAP;\n                    end\n                end else begin\n                    state_index <= queue_curr[curr_read_ptr];\n                    a <= queue_curr[curr_read_ptr][7:4];\n                    b <= queue_curr[curr_read_ptr][3:0];\n                    curr_read_ptr <= curr_read_ptr + 8'd1;\n                    curr_count <= curr_count - 8'd1;\n                    if (t[a] != t[b]) begin\n                        result <= {1'b0, step};\n                        done <= 1'b1;\n                        state <= DONE;\n                    end else begin\n                        state <= ENQUEUE_LEFT;\n                    end\n                end\n            end\n\n            ENQUEUE_LEFT: begin\n                next_a <= left[a];\n                next_b <= left[b];\n                if (!visited[{next_a, next_b}]) begin\n                    visited[{next_a, next_b}] <= 1'b1;\n                    queue_next[next_write_ptr] <= {next_a, next_b};\n                    next_write_ptr <= next_write_ptr + 8'd1;\n                    next_count <= next_count + 8'd1;\n                end\n                state <= ENQUEUE_RIGHT;\n            end\n\n            ENQUEUE_RIGHT: begin\n                next_a <= right[a];\n                next_b <= right[b];\n                if (!visited[{next_a, next_b}]) begin\n                    visited[{next_a, next_b}] <= 1'b1;\n                    queue_next[next_write_ptr] <= {next_a, next_b};\n                    next_write_ptr <= next_write_ptr + 8'd1;\n                    next_count <= next_count + 8'd1;\n                end\n                state <= CHECK;\n            end\n\n            SWAP: begin\n                curr_read_ptr <= 8'd0;\n                curr_write_ptr <= next_write_ptr;\n                curr_count <= next_count;\n                next_write_ptr <= 8'd0;\n                next_count <= 8'd0;\n                step <= step + 8'd1;\n                state <= CHECK;\n            end\n\n            DONE: begin\n                // Stay here until reset\n            end\n\n            INDIST: begin\n                result <= {1'b1, 8'b0};\n                done <= 1'b1;\n                state <= DONE;\n            end\n\n            default: begin\n                state <= IDLE;\n            end\n        endcase\n    end\nend\n\nendmodule